before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>

int compare_int(const void *left, const void *right) {
 const int *a = left;
 const int *b = right;
 return (*a > *b) - (*a < *b);
}
int main(void) {
 int a[] = {3, 1, 2};
 qsort(a, 3, sizeof a[0], compare_int);
 printf("%d %d %d\n", a[0], a[1], a[2]);
}
```

